67:                     const parts = u.pathname.split('/').filter(Boolean);
68:                     if (parts.length >= 4 && (parts[2] === 'blob' || parts[2] === 'raw')) {
69:                         const user = parts[0];
70:                         const repo = parts[1];
71:                         const branch = parts[3];
72:                         const rest = parts.slice(4).join('/');
73:                         return `https://raw.githubusercontent.com/${user}/${repo}/${branch}/${rest}`;
74:                     }
75:                 }
76:             } catch (e) {
77:                 // Not a valid URL or other parsing error, return original
78:             }
79:             return url;
