468:         function findTextElements(node, list = []) {
469:             if (!node) return list;
470:             
471:             // Skip code blocks, math blocks, scripts, styles, page breaks
472:             if (node.tagName === 'PRE' || node.tagName === 'CODE' || 
473:                 node.classList?.contains('katex') || node.classList?.contains('katex-display') ||
474:                 node.tagName === 'SCRIPT' || node.tagName === 'STYLE' ||
475:                 node.classList?.contains('page-break')) {
476:                 return list;
477:             }
478:             
479:             const searchableTags = ['P', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'TD', 'TH', 'BLOCKQUOTE', 'FIGCAPTION', 'LI'];
480:             
481:             // If it's a searchable tag, index it and do not recurse into its children
482:             let hasSearchableChild = false;
483:             for (let i = 0; i < node.children.length; i++) {
484:                 const child = node.children[i];
485:                 if (searchableTags.includes(child.tagName) || child.querySelector(searchableTags.join(','))) {
486:                     hasSearchableChild = true;
487:                     break;
488:                 }
489:             }
490:             
491:             if (searchableTags.includes(node.tagName) && !hasSearchableChild) {
492:                 list.push(node);
493:             } else {
494:                 for (let i = 0; i < node.children.length; i++) {
495:                     findTextElements(node.children[i], list);
496:                 }
497:             }
