508:         function splitIntoSentences(text) {
509:             if (!text) return [];
510:             const cleanText = text.replace(/\s+/g, ' ').trim();
511:             if (!cleanText) return [];
512:             
513:             const regex = /[^.!?]+(?:[.!?]+|$)/g;
514:             const sentences = [];
515:             let match;
516:             while ((match = regex.exec(cleanText)) !== null) {
517:                 const sentence = match[0].trim();
518:                 if (sentence.length > 3) { // ignore very short text snippets
519:                     sentences.push(sentence);
520:                 }
521:             }
522:             return sentences;
523:         }
