528:             // 1. Check YAML front matter (--- ... ---)
529:             const yamlMatch = markdown.match(/^---\s*\r?\n([\s\S]*?)\r?\n---/);
530:             if (yamlMatch) {
531:                 const yamlContent = yamlMatch[1];
532:                 // Support bracketed inline list: tags: [a, b, c]
533:                 const inlineListMatch = yamlContent.match(/tags:\s*\[(.*?)\]/i);
534:                 if (inlineListMatch) {
535:                     return inlineListMatch[1].split(',').map(t => t.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
536:                 }
537:                 // Support bulleted list: tags:\n  - a\n  - b
538:                 const bulletListMatch = yamlContent.match(/tags:\s*\r?\n((?:\s*-\s*[^\r\n]+\r?\n?)+)/i);
539:                 if (bulletListMatch) {
540:                     return bulletListMatch[1].split(/\r?\n/).map(line => line.replace(/^\s*-\s*/, '').trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
541:                 }
542:                 // Support comma-separated: tags: a, b, c
543:                 const commaMatch = yamlContent.match(/tags:\s*([^\r\n]+)/i);
544:                 if (commaMatch) {
545:                     return commaMatch[1].split(',').map(t => t.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
546:                 }
547:             }
548: 
549:             // 2. Legacy HTML comment tags (<!-- tags: ... -->)
550:             const commentMatch = markdown.match(/<!--[\s\S]*?tags:\s*([^\r\n\--->]+)[\s\S]*?-->/i);
551:             if (commentMatch) {
552:                 return commentMatch[1].split(',').map(t => t.trim()).filter(Boolean);
553:             }
554:             return [];
555:         }
